function ico(nombre, clase = "") {
  if (ICONOS_IMG[nombre]) return `<img class="ico ico-img ${clase}" src="${icoUrl(nombre)}" alt="" aria-hidden="true" draggable="false">`;
  return `<svg class="ico ${clase}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${ICONOS[nombre] || ""}</svg>`;
}
// Cada ícono pasa de data: (3 a 10 KB de texto en cada <img>) a una dirección blob: corta. Así el navegador lee y dibuja
// cada ícono una sola vez aunque aparezca cientos de veces, y el HTML que se arma es mucho más corto. Sigue sin internet.
// Se convierte cada ícono la primera vez que se usa, no todos al abrir.
const ICO_URL = {};
function icoUrl(k) {
  if (ICO_URL[k]) return ICO_URL[k];
  let u = ICONOS_IMG[k];
  const m = typeof Blob !== "undefined" && window.URL && URL.createObjectURL && /^data:([^;,]+);base64,(.*)$/.exec(u || "");
  if (m) try {
    const bin = atob(m[2]), a = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
    u = URL.createObjectURL(new Blob([a], { type: m[1] }));
  } catch {}
  return (ICO_URL[k] = u);
}
// pinta los <i data-ico="…"> fijos del HTML
function pintarIconos(root = document) {
  root.querySelectorAll("i[data-ico]").forEach((el) => { if (!el.firstChild) el.outerHTML = ico(el.dataset.ico, el.className); });
}
// botones cuyo texto empieza con un emoji: el emoji se cambia por el ícono
const CON_ICONO = [["#tourBtn", "recorrido"], ["#modeBtn", "todo"], [".print", "calendario"], [".share", "compartir"],
  ["#verBienvenida", "hola"], ["#verLeer", "proyecto"], ["[data-i18n=mapaBtn]", "mapa"], ["[data-i18n=vistaTec]", "tecnica"], ["[onclick*=docs]", "proyecto"],
  ["#pickGps", "gps"]];
const SIN_EMOJI = /^[\p{Extended_Pictographic}\p{So}\uFE0F\u200D\s☰▶➜]+/u;
function decorarIconos(root = document) {
  for (const [sel, nombre] of CON_ICONO) {
    root.querySelectorAll(sel).forEach((el) => {
      if (el.querySelector(":scope > .ico")) return;
      const t = el.textContent.replace(SIN_EMOJI, "").replace(/\s*→\s*$/, "").trim();
      el.innerHTML = `${ico(nombre)}<span>${t.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c])}</span>`;
    });
  }
  pintarIconos(root);
}

// ---------------------------------------------------------------- los emojis del texto se dibujan con los íconos de Muyuy
// Así se ven igual en todos los celulares. Se cambian en la pantalla, no en los textos: la voz y el chat no cambian.
