const EMOJI_RE = new RegExp(`(${Object.keys(EMOJI_ICO).sort((a, b) => b.length - a.length).join("|")})\uFE0F?`, "gu");
const EMOJI_1 = new RegExp(EMOJI_RE.source, "u");
const EMOJI_NO ="#juegos, svg, script, style, textarea, select, option, title, input, noscript";
function emojisEnTexto(t) {
  const v = t.nodeValue;
  if (!v || !t.parentElement) return;
  EMOJI_RE.lastIndex = 0;
  if (!EMOJI_RE.test(v)) return; // primero lo barato: casi ningún texto tiene emojis
  EMOJI_RE.lastIndex = 0;
  if (t.parentElement.closest(EMOJI_NO)) return;
  const f = document.createDocumentFragment();
  let i = 0;
  for (const m of v.matchAll(EMOJI_RE)) {
    if (m.index < i) continue; // quedó dentro de la palabra pegada al emoji anterior
    if (m.index > i) f.append(v.slice(i, m.index));
    const img = new Image();
    img.className = "emo"; img.alt = ""; img.draggable = false; const k = EMOJI_ICO[m[1]]; img.src = k.startsWith("c:") ? CULT_IMG[k.slice(2)] : icoUrl(k);
    i = m.index + m[0].length;
    // el ícono va pegado a la palabra que sigue: si no, al partirse el texto en un botón angosto (sobre todo en inglés
    // y quechua) el ícono queda solo en una línea y el texto en otra
    const g = /^[  ]?[^\s]+/.exec(v.slice(i));
    if (g && !EMOJI_1.test(g[0])) {
      // espacio que no se parte (o unión invisible si no hay espacio): el ícono y la palabra van juntos, pero el resto
      // del texto se sigue repartiendo parejo entre las líneas (text-wrap: balance)
      const w = document.createElement("span"); w.className = "emo-w"; w.append(img, /^\s/.test(g[0]) ? " " + g[0].slice(1) : "⁠" + g[0]); f.append(w);
      i += g[0].length;
    } else f.append(img);
  }
  if (i < v.length) f.append(v.slice(i));
  const p = t.parentElement;
  if (p.childNodes.length === 1 && p.matches("button, .back, a.btn, a.ah-btn, summary")) { // el botón es flex: ícono y texto sueltos se separan al partirse la línea
    const s = document.createElement("span"); s.className = "bt-t"; s.append(f); return t.replaceWith(s);
  }
  t.replaceWith(f);
}
function emojisEn(n) {
  if (n.nodeType === 3) return emojisEnTexto(n);
  if (n.nodeType !== 1 || n.closest(EMOJI_NO)) return;
  const w = document.createTreeWalker(n, NodeFilter.SHOW_TEXT), l = [];
  while (w.nextNode()) l.push(w.currentNode);
  l.forEach(emojisEnTexto);
}
// botón con ícono y texto sueltos: en un botón flex, al partirse el texto en dos líneas el ícono queda lejos.
// Se juntan en un solo <span> para que el ícono vaya pegado a la primera palabra.
const BOTON = "button, a.back, a.btn, a.ah-btn";
function candidatoBoton(b) { // solo mira la estructura: no le pide estilos al navegador
  if (b.closest(EMOJI_NO) || b.querySelector(":scope > .bt-t")) return false;
  const hijos = b.childNodes;
  if (hijos.length < 2) return false;
  let texto = false;
  for (const x of hijos) {
    if (x.nodeType === 3 && x.nodeValue.trim()) texto = true;
    else if (x.nodeType === 1 && /^(INPUT|SELECT|TEXTAREA|DIV|UL|OL|P)$/.test(x.tagName)) return false;
  }
  return texto;
}
// primero se leen los estilos de todos los botones y después se cambian: leer y cambiar de a uno obligaba al
// navegador a recalcular los estilos de la página en cada botón
function juntarBotones(lista) {
  const flex = lista.filter((b) => /flex|grid/.test(getComputedStyle(b).display));
  flex.forEach((b) => { const s = document.createElement("span"); s.className = "bt-t"; s.append(...b.childNodes); b.append(s); });
}
function botonesEn(n, lista) {
  if (n.nodeType === 3) n = n.parentElement;
  if (!n || n.nodeType !== 1) return;
  const b = n.closest(BOTON); if (b && candidatoBoton(b)) lista.add(b);
  n.querySelectorAll(BOTON).forEach((x) => { if (candidatoBoton(x)) lista.add(x); });
}
function juntarEn(n) { const l = new Set(); botonesEn(n, l); juntarBotones([...l]); }
function vigilarEmojis() {
  emojisEn(document.body);
  juntarEn(document.body);
  // los cambios se juntan y se procesan una vez antes de dibujar: antes cada cambio recorría su parte de la página
  // y al cambiar de idioma o de chacra eso trababa el celular
  const nodos = new Set(), textos = new Set();
  let turno = 0;
  const procesar = () => {
    turno = 0;
    const ts = [...textos], ns = [...nodos], todos = new Set(ns);
    textos.clear(); nodos.clear();
    ts.forEach((t) => { if (t.isConnected) emojisEnTexto(t); });
    const raices = ns.filter((n) => {
      if (!n.isConnected) return false;
      for (let a = n.parentNode; a; a = a.parentNode) if (todos.has(a)) return false; // ya lo cubre un nodo de más arriba
      return true;
    });
    raices.forEach(emojisEn); // primero todos los cambios de emojis…
    const botones = new Set(); raices.forEach((n) => botonesEn(n, botones));
    juntarBotones([...botones]); // …y los botones al final, con una sola lectura de estilos
  };
  new MutationObserver((ms) => {
    ms.forEach((m) => { if (m.type === "characterData") textos.add(m.target); else m.addedNodes.forEach((n) => nodos.add(n)); });
    if (!turno) turno = requestAnimationFrame(procesar);
  }).observe(document.body, { childList: true, subtree: true, characterData: true });
}
// En la web publicada todos los scripts van en un solo archivo y CULT_IMG se define más abajo: hay que esperar a que termine.
// Son solo dibujos: si algo falla aquí, la app sigue abriendo con sus emojis.
function arrancarEmojis() { setTimeout(() => { try { vigilarEmojis(); } catch (e) { console.warn("Íconos del texto:", e); } }, 0); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancarEmojis); else arrancarEmojis();
